package dev.toka.profiles;
import org.junit.*;import static org.junit.Assert.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import dev.toka.profiles.model.*;import dev.toka.profiles.storage.*;import dev.toka.storage.*;
public class ProfileTest { private static Path testRoot() throws java.io.IOException { Path p=Path.of(".build-tools/tests");Files.createDirectories(p);return p; }
 private Profile p(UUID u,String name,String legacy){return new Profile(u,name,Set.of(name+"Old"),Map.of("firstWindow","0"),legacy);}
 @Test public void immutableAndStrictIdentity(){UUID u=UUID.randomUUID();Profile p=p(u,"Sunny","12");assertEquals(u,p.profileId());try{p.preferences().put("x","y");fail();}catch(UnsupportedOperationException expected){}var json=ProfileCodec.encode(p);json.addProperty("profileId",UUID.randomUUID().toString());try{ProfileCodec.decode(json);fail();}catch(IllegalArgumentException expected){}json=ProfileCodec.encode(p);json.remove("uuid");try{ProfileCodec.decode(json);fail();}catch(IllegalArgumentException expected){}}
 @Test public void backendPersistenceAndIndexes()throws Exception{for(Backend b:Backend.values()){Path path=Files.createTempDirectory(testRoot(),"profiles-").resolve("data");var config=new StoreConfig(b,path,1);UUID u=UUID.randomUUID();try(var repo=ProfileRepository.open(config,4)){repo.put(p(u,"Sunny","12")).get(5,TimeUnit.SECONDS);assertEquals(u,repo.findByName("SUNNYOLD").orElseThrow().uuid());try{repo.put(p(UUID.randomUUID(),"sunny","13")).get();fail();}catch(ExecutionException expected){}assertEquals(1,repo.snapshot().size());assertEquals(ProfileRepository.State.READY,repo.state());}try(var repo=ProfileRepository.open(config,4)){assertEquals("0",repo.find(u).orElseThrow().preferences().get("firstWindow"));assertEquals(1,repo.snapshot().size());}}}
 @Test public void startupRejectsConflictingAliases()throws Exception{Path path=Files.createTempDirectory(testRoot(),"profiles-conflict").resolve("data");var config=new StoreConfig(Backend.SQLITE,path,1);UUID a=UUID.randomUUID(),b=UUID.randomUUID();try(var store=DocumentStore.open(config)){store.save(ProfileCodec.key(a),ProfileCodec.encode(p(a,"Sunny","1")));store.save(ProfileCodec.key(b),ProfileCodec.encode(p(b,"SUNNY","2")));}try(var repo=ProfileRepository.open(config,2)){fail();}catch(java.io.IOException expected){} }
}
